$('addAll').addEventListener('click',()=>{EVS.forEach((e,i)=>setTimeout(()=>window.open(gcal(e),'_blank','noopener'),i*900))});
$('rsSeal').addEventListener('click',()=>{const w=$('rsw'),o=w.hidden;w.hidden=!o;$('rsSeal').setAttribute('aria-expanded',String(o));$('rsHint').hidden=o;if(o)setTimeout(()=>w.scrollIntoView({behavior:'smooth',block:'start'}),120)});
$('vnm').innerHTML=[...'Noor Mahal'].map((c,i)=>`<span aria-hidden="true" style="--i:${i}">${c===' '?'&nbsp;':c}</span>`).join('');
$('copyAddr').addEventListener('click',()=>{const t='Noor Mahal, Bahawalpur, Punjab, Pakistan',d=()=>{$('toast').textContent='Address copied';setTimeout(()=>$('toast').textContent='',2200)};navigator.clipboard&&navigator.clipboard.writeText?navigator.clipboard.writeText(t).then(d,d):d()});
